import Capacitor
import Network
import UIKit
import WebKit

/// Registers the local Sign in with Apple plugin. Package.swift is generated by cap sync.
/// The iOS binary never sends the Samsung or Huawei store token.
/// Dynamic Type writes --ke-text-scale so larger system text grows the layout.
class KidEaseBridgeViewController: CAPBridgeViewController {
    private var textScaleScript: WKUserScript?
    private var offlineTimer: DispatchWorkItem?
    private var offlineWaits = 0
    private let pathMonitor = NWPathMonitor()
    private var showingOffline = false
    override open func instanceDescriptor() -> InstanceDescriptor {
        let descriptor = super.instanceDescriptor()
        descriptor.appendedUserAgentString = Self.ensureNativeToken(Self.withoutForeignStoreToken(descriptor.appendedUserAgentString))
        descriptor.overridenUserAgentString = Self.withoutForeignStoreToken(descriptor.overridenUserAgentString)
        if let server = descriptor.serverURL {
            descriptor.serverURL = Self.withoutSamsungStoreQuery(server)
        }
        return descriptor
    }

    /// In-app path from a home-screen shortcut. Other URLs are ignored.
    func openAppPath(_ path: String) {
        guard path.hasPrefix("/"), !path.hasPrefix("//"), !path.contains("'"), !path.contains("\\") else { return }
        webView?.evaluateJavaScript("window.location.assign('\(path)')")
    }

    override open func capacitorDidLoad() {
        super.capacitorDidLoad()
        bridge?.registerPluginInstance(AppleSignInPlugin())
        bridge?.registerPluginInstance(ApplePlatformPlugin())
        bridge?.registerPluginInstance(AuthSessionPlugin())
        bridge?.registerPluginInstance(SecureSessionPlugin())
        bridge?.registerPluginInstance(PdfShareFilesPlugin())
        bridge?.registerPluginInstance(CallKitVoipPlugin())
        bridge?.registerPluginInstance(AdminWebOnlyPlugin())
        if let controller = webView?.configuration.userContentController {
            installTextScaleScript(on: controller)
        }
        NotificationCenter.default.addObserver(
            self,
            selector: #selector(contentSizeChanged),
            name: UIContentSizeCategory.didChangeNotification,
            object: nil
        )
        startOfflineWatch()
    }

    /// The live site never loaded, or the network dropped. Show the bundled page.
    /// NWPathMonitor reports a brief "unsatisfied" right after a relaunch, so a
    /// drop is rechecked before the page shows, and a slow load on a working
    /// network is never called offline.
    private func startOfflineWatch() {
        scheduleOfflineCheck(after: 20)
        pathMonitor.pathUpdateHandler = { [weak self] path in
            DispatchQueue.main.async {
                guard let self else { return }
                if path.status == .satisfied {
                    if self.remotePageReady { self.showingOffline = false }
                    if self.showingOffline { self.recoverFromOffline() }
                    return
                }
                DispatchQueue.main.asyncAfter(deadline: .now() + 2.5) { [weak self] in
                    guard let self, self.pathMonitor.currentPath.status != .satisfied else { return }
                    self.showOfflinePage()
                }
            }
        }
        pathMonitor.start(queue: DispatchQueue(label: "ca.kidease.offline"))
    }

    private func scheduleOfflineCheck(after seconds: TimeInterval) {
        offlineTimer?.cancel()
        let work = DispatchWorkItem { [weak self] in
            self?.offlineTimedOut()
        }
        offlineTimer = work
        DispatchQueue.main.asyncAfter(deadline: .now() + seconds, execute: work)
    }

    private func offlineTimedOut() {
        if remotePageReady {
            offlineTimer?.cancel()
            return
        }
        if remotePageStarted, webView?.isLoading == true, offlineWaits < 1 {
            offlineWaits += 1
            scheduleOfflineCheck(after: 8)
            return
        }
        if pathMonitor.currentPath.status == .satisfied {
            // Online but slow. Ask the site before calling it offline.
            probeSite { [weak self] reachable in
                guard let self else { return }
                if reachable && self.offlineWaits < 3 {
                    self.offlineWaits += 1
                    if self.offlineWaits == 2 { self.loadLiveSite() }
                    self.scheduleOfflineCheck(after: 10)
                } else if !reachable {
                    self.showOfflinePage()
                }
            }
            return
        }
        showOfflinePage()
    }

    /// Any HTTP answer from kidease.ca means the network works.
    private func probeSite(_ done: @escaping (Bool) -> Void) {
        guard let url = URL(string: "https://www.kidease.ca/robots.txt?ke-probe=\(Int(Date().timeIntervalSince1970))") else { return done(true) }
        var request = URLRequest(url: url, cachePolicy: .reloadIgnoringLocalCacheData, timeoutInterval: 6)
        request.httpMethod = "HEAD"
        URLSession.shared.dataTask(with: request) { _, response, _ in
            DispatchQueue.main.async { done(response is HTTPURLResponse) }
        }.resume()
    }

    private func loadLiveSite() {
        let raw = bridge?.config.serverURL.absoluteString ?? "https://www.kidease.ca/"
        guard let url = URL(string: raw) else { return }
        webView?.load(URLRequest(url: url))
    }

    /// Back online while the bundled page shows: reopen the live site by itself.
    private func recoverFromOffline() {
        probeSite { [weak self] reachable in
            guard let self, reachable, self.showingOffline else { return }
            self.showingOffline = false
            self.offlineWaits = 0
            self.loadLiveSite()
            self.scheduleOfflineCheck(after: 20)
        }
    }

    private var remotePageStarted: Bool {
        guard let url = webView?.url, let host = url.host?.lowercased() else { return false }
        let scheme = url.scheme?.lowercased() ?? ""
        if scheme == "capacitor" || scheme == "kidease" || scheme == "file" { return false }
        return host == "www.kidease.ca" || host == "kidease.ca"
    }

    private var remotePageReady: Bool {
        remotePageStarted && webView?.isLoading == false
    }

    private func showOfflinePage() {
        guard let webView else { return }
        if showingOffline { return }
        let path = webView.url?.path ?? ""
        if path.hasSuffix("/index.html") && !remotePageStarted { return }
        showingOffline = true
        offlineTimer?.cancel()
        if let errorURL = bridge?.config.errorPathURL {
            webView.load(URLRequest(url: errorURL))
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) { [weak self] in
            self?.injectSavedShortlist()
            self?.bridge?.eval(js: "try{Capacitor.Plugins.SplashScreen.hide()}catch(e){}")
        }
    }

    private func injectSavedShortlist() {
        let raw = UserDefaults.standard.string(forKey: "CapacitorStorage.ke-offline-shortlist") ?? "[]"
        let js = "window.keRenderSaved && window.keRenderSaved(\(Self.jsonLiteral(raw)))"
        webView?.evaluateJavaScript(js, completionHandler: nil)
    }

    private static func jsonLiteral(_ raw: String) -> String {
        let data = Data(raw.utf8)
        guard let parsed = try? JSONSerialization.jsonObject(with: data),
              let safe = try? JSONSerialization.data(withJSONObject: parsed),
              let text = String(data: safe, encoding: .utf8) else { return "[]" }
        return text
    }

    /// The web view always fills the window at device width. A page wider than the screen
    /// made WKWebView zoom out, so zoom-out stays blocked. Pinch in is allowed.
    override open func viewDidLayoutSubviews() {
        super.viewDidLayoutSubviews()
        guard let webView = webView else { return }
        if webView.frame != view.bounds { webView.frame = view.bounds }
        webView.autoresizingMask = [.flexibleWidth, .flexibleHeight]
        webView.allowsBackForwardNavigationGestures = true
        // Keep the page from zooming out and letterboxing. Pinch in stays on.
        if #available(iOS 14.0, *), webView.pageZoom < 1 { webView.pageZoom = 1 }
        let scroll = webView.scrollView
        scroll.minimumZoomScale = 1
        scroll.maximumZoomScale = 3
        if scroll.zoomScale < 1 { scroll.setZoomScale(1, animated: false) }
        scroll.contentInsetAdjustmentBehavior = .never
    }

    deinit {
        offlineTimer?.cancel()
        pathMonitor.cancel()
        NotificationCenter.default.removeObserver(self)
    }

    /// Fold, unfold, rotation, and iPad Split View change the window size.
    /// The web view follows Auto Layout. Reloading here would drop a call.
    override open func viewWillTransition(to size: CGSize, with coordinator: UIViewControllerTransitionCoordinator) {
        super.viewWillTransition(to: size, with: coordinator)
    }

    @objc private func contentSizeChanged() {
        if let controller = webView?.configuration.userContentController {
            installTextScaleScript(on: controller)
        }
        applyTextScale()
    }

    /// Larger than Large grows the root font. Large stays at the current 14px design.
    static func textScale(for category: UIContentSizeCategory) -> String {
        switch category {
        case .extraSmall: return "0.82"
        case .small: return "0.88"
        case .medium: return "0.94"
        case .large: return "1"
        case .extraLarge: return "1.12"
        case .extraExtraLarge: return "1.23"
        case .extraExtraExtraLarge: return "1.35"
        case .accessibilityMedium: return "1.50"
        case .accessibilityLarge: return "1.64"
        case .accessibilityExtraLarge: return "1.79"
        case .accessibilityExtraExtraLarge: return "1.93"
        case .accessibilityExtraExtraExtraLarge: return "2.12"
        default: return "1"
        }
    }

    private func installTextScaleScript(on controller: WKUserContentController) {
        // WKUserContentController has no single-script removal. Later scripts run after
        // earlier ones, so the newest scale wins without touching Capacitor's own scripts.
        let scale = Self.textScale(for: UIApplication.shared.preferredContentSizeCategory)
        let source = "document.documentElement.style.setProperty('--ke-text-scale','\(scale)');"
        let script = WKUserScript(source: source, injectionTime: .atDocumentStart, forMainFrameOnly: true)
        controller.addUserScript(script)
        textScaleScript = script
    }

    private func applyTextScale() {
        let scale = Self.textScale(for: UIApplication.shared.preferredContentSizeCategory)
        webView?.evaluateJavaScript("document.documentElement.style.setProperty('--ke-text-scale','\(scale)')")
    }

    /// Every iOS shell sends KidEaseNative so the website can hide Admin before paint.
    static func ensureNativeToken(_ agent: String?) -> String {
        let token = "KidEaseNative"
        let base = (agent ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        if base.contains(token) { return base }
        if base.isEmpty { return token }
        return base + " " + token
    }

    /// KidEaseStoreSamsung belongs to the Galaxy Store flavour only.
    static func withoutForeignStoreToken(_ agent: String?) -> String? {
        guard let agent else { return nil }
        let cleaned = agent
            .replacingOccurrences(of: "KidEaseStoreSamsung", with: "")
            .replacingOccurrences(of: "KidEaseStoreHuawei", with: "")
            .replacingOccurrences(of: "KidEaseStoreAmazon", with: "")
            .replacingOccurrences(of: "KidEaseNoGms", with: "")
            .replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        return cleaned.isEmpty ? nil : cleaned
    }

    static func withoutSamsungStoreQuery(_ raw: String) -> String {
        guard var parts = URLComponents(string: raw), let items = parts.queryItems else { return raw }
        let next = items.filter { !($0.name == "store" && $0.value == "samsung") }
        if next.count == items.count { return raw }
        parts.queryItems = next.isEmpty ? nil : next
        return parts.string ?? raw
    }
}

/// Cancels /admin and Cloudflare Access navigations so the shell never opens Safari.
/// Keep the path list in step with isAccessProtectedPath in native-admin.ts.
@objc(AdminWebOnlyPlugin)
public class AdminWebOnlyPlugin: CAPPlugin, CAPBridgedPlugin {
    public let identifier = "AdminWebOnlyPlugin"
    public let jsName = "AdminWebOnly"
    public let pluginMethods: [CAPPluginMethod] = []

    public override func shouldOverrideLoad(_ navigationAction: WKNavigationAction) -> NSNumber? {
        guard let url = navigationAction.request.url else { return nil }
        let main = navigationAction.targetFrame == nil || navigationAction.targetFrame?.isMainFrame == true
        if !main || !Self.shouldStayInApp(url) { return nil }
        if let webView = self.webView, let next = Self.noteURL(from: url) {
            DispatchQueue.main.async {
                webView.load(URLRequest(url: next))
            }
        }
        return NSNumber(value: true)
    }

    static func shouldStayInApp(_ url: URL) -> Bool {
        let host = (url.host ?? "").lowercased()
        if host == "cloudflareaccess.com" || host.hasSuffix(".cloudflareaccess.com") { return true }
        let ours = host.isEmpty || host == "kidease.ca" || host == "www.kidease.ca" || host.hasSuffix(".kidease.ca")
        if !ours { return false }
        var path = url.path
        if path.count > 1 && path.hasSuffix("/") { path.removeLast() }
        if path == "/fr" { path = "/" }
        if path.hasPrefix("/fr/") { path = String(path.dropFirst(3)) }
        if path.isEmpty { path = "/" }
        if path == "/use-the-website" || path == "/app-admin-unavailable" { return false }
        if path == "/admin" || path.hasPrefix("/admin/") || path.hasPrefix("/admin-") { return true }
        if path == "/api/admin" || path.hasPrefix("/api/admin/") { return true }
        return false
    }

    static func noteURL(from url: URL) -> URL? {
        var parts = URLComponents()
        parts.scheme = url.scheme == "http" ? "http" : "https"
        let host = (url.host ?? "").lowercased()
        if host == "kidease.ca" || host == "www.kidease.ca" || host.hasSuffix(".kidease.ca") {
            parts.host = url.host
        } else {
            parts.host = "www.kidease.ca"
        }
        let french = url.path == "/fr" || url.path.hasPrefix("/fr/")
        parts.path = french ? "/fr/app-admin-unavailable" : "/app-admin-unavailable"
        return parts.url
    }
}

@objc(PdfShareFilesPlugin)
public class PdfShareFilesPlugin: CAPPlugin, CAPBridgedPlugin {
    public let identifier = "PdfShareFilesPlugin"
    public let jsName = "PdfShareFiles"
    public let pluginMethods = [CAPPluginMethod(name: "stage", returnType: CAPPluginReturnPromise)]

    @objc func stage(_ call: CAPPluginCall) {
        guard let filename = call.getString("filename"),
              filename.range(of: #"^[a-zA-Z0-9_.-]{1,180}\.pdf$"#, options: .regularExpression) != nil,
              let base64 = call.getString("base64"), base64.utf8.count <= 28_000_000,
              let data = Data(base64Encoded: base64) else {
            call.reject("Invalid PDF")
            return
        }
        do {
            let files = FileManager.default
            let root = files.temporaryDirectory.appendingPathComponent("shared-pdfs", isDirectory: true)
            let cutoff = Date().addingTimeInterval(-86_400)
            let previous = try? files.contentsOfDirectory(at: root, includingPropertiesForKeys: [.creationDateKey])
            for item in previous ?? [] {
                if let date = try? item.resourceValues(forKeys: [.creationDateKey]).creationDate, date < cutoff {
                    try? files.removeItem(at: item)
                }
            }
            let folder = root.appendingPathComponent(UUID().uuidString, isDirectory: true)
            try files.createDirectory(at: folder, withIntermediateDirectories: true)
            let file = folder.appendingPathComponent(filename)
            try data.write(to: file, options: [.atomic, .completeFileProtection])
            call.resolve(["uri": file.absoluteString])
        } catch {
            call.reject("Could not prepare PDF")
        }
    }
}
